with tab_conteudo:

    import streamlit as st
    import numpy as np
    import pandas as pd
    import plotly.graph_objects as go
    from scipy import stats
    
    # Título do Subtópico
    st.header(r"Definição Matemática e Propriedades dos Resíduos")
    
    # Prosa Teórica
    st.markdown(r"""
    No estudo da regressão linear, o objetivo central é descrever a relação entre uma variável de interesse e um conjunto de variáveis explicativas através de um modelo estocástico. Contudo, a predição perfeita é raramente alcançada, resultando em uma discrepância entre os valores observados e os valores preditos: os **resíduos**.
    """)
    
    st.info(r"Em termos práticos, um resíduo representa a parcela desconhecida ou o erro individual que o modelo não conseguiu capturar. Se o ajuste for adequado, os resíduos devem se comportar como ruído aleatório.")
    
    st.markdown(r"""
    Padrões estruturados nos resíduos indicam, quase invariavelmente, falhas de especificação ou violações de premissas clássicas. Para que a inferência estatística seja válida, observamos as seguintes condições:
    - **Homocedasticidade**: A variância do resíduo deve ser constante ao longo de todo o espectro dos dados.
    - **Independência**: O resíduo de uma observação não deve carregar informações sobre a vizinhança.
    - **Normalidade**: Espera-se que a distribuição dos erros siga uma curva de Gauss, validando a teoria de testes de hipóteses (t-student).
    """)
    
    # Formalismo Matemático
    st.subheader(r"📐 A Geometria dos Erros: Formalismo e Ortogonalidade")
    st.markdown(r"Matematicamente, os resíduos são definidos pela projeção ortogonal do vetor de observações $\mathbf{Y}$ no espaço definido pela matriz de desenho $\mathbf{X}$. A peça central que formaliza essa operação é a matriz hat:")
    
    st.latex(r"\hat{\mathbf{e}} = \mathbf{Y} - \hat{\mathbf{Y}} = (\mathbf{I} - \mathbf{H})\mathbf{Y}, \quad \mathbf{H} = \mathbf{X}(\mathbf{X}^{\top}\mathbf{X})^{-1}\mathbf{X}^{\top}")
    
    # Dedução Analítica
    st.markdown(r"A dedução do comportamento ortogonal dos resíduos é demonstrada a seguir:")
    st.latex(r"\mathbf{X}^{\top}\mathbf{X}\hat{\boldsymbol{\beta}} = \mathbf{X}^{\top}\mathbf{Y}")
    st.latex(r"\hat{\mathbf{Y}} = \mathbf{X}\hat{\boldsymbol{\beta}} = \mathbf{H}\mathbf{Y}")
    st.latex(r"\hat{\mathbf{e}} = (\mathbf{I} - \mathbf{H})\mathbf{Y}")
    st.latex(r"\mathbf{X}^{\top}\hat{\mathbf{e}} = \mathbf{X}^{\top}(\mathbf{I} - \mathbf{H})\mathbf{Y} = \mathbf{0}")
    
    # Simulador Interativo
    st.subheader(r"⚙️ Visualizador de Projeção Ortogonal")
    st.markdown(r"Edite a tabela abaixo para ajustar os pontos em tempo real e visualizar como a reta de regressão e os resíduos (segmentos verticais) se comportam.")
    
    if 'df_regressao_subtopico_1' not in st.session_state:
        st.session_state['df_regressao_subtopico_1'] = pd.DataFrame({'X': [10.0, 20.0, 30.0, 40.0, 50.0], 'Y': [105.0, 95.0, 145.0, 160.0, 210.0]})
    
    df_edited = st.data_editor(st.session_state['df_regressao_subtopico_1'], use_container_width=True, key=r"data_editor_subtopico_1")
    st.session_state['df_regressao_subtopico_1'] = df_edited
    
    slope, intercept, _, _, _ = stats.linregress(df_edited['X'], df_edited['Y'])
    y_pred = slope * df_edited['X'] + intercept
    
    fig = go.Figure()
    fig.add_trace(go.Scatter(x=df_edited['X'], y=df_edited['Y'], mode='markers', name='Observações', marker=dict(color='#1E3A8A', size=10)))
    fig.add_trace(go.Scatter(x=df_edited['X'], y=y_pred, mode='lines', name='Reta Ajustada', line=dict(color='#10B981', width=2)))
    
    for i in range(len(df_edited)):
        fig.add_trace(go.Scatter(x=[df_edited['X'][i], df_edited['X'][i]], y=[df_edited['Y'][i], y_pred[i]], mode='lines', line=dict(color='#991B1B', width=1, dash='dot'), showlegend=False))
    
    fig.update_layout(
        template="plotly_white",
        height=420,
        margin=dict(l=55, r=30, t=65, b=55, pad=4),
        title=dict(text="<b>Projeção Ortogonal e Resíduos</b>", font=dict(size=14, color="#1E293B"), x=0.0, y=0.95),
        xaxis=dict(title=dict(text="Variável Explicativa X", font=dict(size=11, color="#1E293B")), tickfont=dict(size=9, color="#64748B"), gridcolor="#E2E8F0", zerolinecolor="#CBD5E1", fixedrange=True),
        yaxis=dict(title=dict(text="Variável Resposta Y", font=dict(size=11, color="#1E293B")), tickfont=dict(size=9, color="#64748B"), gridcolor="#E2E8F0", zerolinecolor="#CBD5E1", fixedrange=True),
        legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1.0, font=dict(size=9, color="#64748B")),
        hoverlabel=dict(bgcolor="#FFFFFF", font_size=12, font_color="#1E293B")
    )
    
    st.plotly_chart(fig, use_container_width=True, key=r"plotly_chart_subtopico_1")
    
    st.info(f"O modelo atual apresenta um coeficiente angular de {slope:.2f}. A soma dos quadrados dos resíduos (SQRes) reflete o grau de incerteza que a reta não conseguiu explicar com a configuração atual de pontos.")
    
    # Exemplos Práticos
    st.subheader(r"📈 Casos de Aplicação Prática: Análise Industrial")
    
    with st.container(border=True):
        st.markdown(r"##### 📖 Exemplo Resolvido: Eficácia de Custo")
        st.markdown(r"Em uma análise industrial, o custo de produção ($Y$) foi avaliado em relação à quantidade produzida ($X$). Dados: $(10, 100), (20, 90), (30, 150)$.")
        st.latex(r"\mathbf{X} = \begin{pmatrix} 1 & 10 \\ 1 & 20 \\ 1 & 30 \end{pmatrix}, \mathbf{Y} = \begin{pmatrix} 100 \\ 90 \\ 150 \end{pmatrix}")
        st.markdown(r"**Desenvolvimento Aritmético Passo a Passo:**")
        st.markdown(r"- Cálculo de $(\mathbf{X}^{\top}\mathbf{X})^{-1}$ resulta na inversão da matriz de dispersão.")
        st.markdown(r"- Estimativa dos coeficientes: $\hat{\beta}_0 = 46.67$ e $\hat{\beta}_1 = 2.5$.")
        st.markdown(r"- Vetor de resíduos calculado: $\hat{\mathbf{e}} = [28.33, -6.67, 28.33]^{\top}$.")
        st.success(r"O vetor de resíduos revela que o modelo subestima significativamente o custo na primeira e na terceira observação. Este resultado sugere uma possível curvatura no fenômeno, indicando que um termo quadrático pode ser necessário.")

    import streamlit as st
    import numpy as np
    import plotly.graph_objects as go
    from plotly.subplots import make_subplots
    from scipy import stats
    
    # --- Cabeçalho do Subtópico ---
    st.header(r"Diagnóstico e Validação de Pressupostos")
    
    st.markdown(r"""
    A construção de um modelo estatístico, por mais sofisticado que seja em sua formulação algorítmica ou em sua complexidade matricial, repousa invariavelmente sobre uma base de fé teórica: a hipótese de que a estrutura imposta aos dados reflete adequadamente a realidade subjacente.
    """)
    
    st.warning(r"O diagnóstico não é uma etapa burocrática, mas sim o critério de demarcação entre a ciência robusta e o ruído computacional.")
    
    # --- Listagem de Pressupostos ---
    st.markdown(r"""
    ### 📋 Os Pilares do Modelo Linear
    A integridade das inferências depende de quatro suposições fundamentais que devem ser validadas:
    - **Linearidade**: O valor esperado da variável resposta $\mathbf{Y}$ deve ser uma função linear da matriz de desenho $\mathbf{X}$.
    - **Homocedasticidade**: A variância do ruído deve ser constante para todas as observações, evitando que intervalos de confiança sejam artificialmente distorcidos.
    - **Independência dos Erros**: Cada observação deve conter informação não redundante; correlações espaciais ou temporais invalidam as estimativas de $SQRes$.
    - **Normalidade**: A distribuição dos erros deve ser Gaussiana, garantindo a validade das distribuições $t$ e $F$ nos testes de hipóteses.
    """)
    
    # --- Formalismo Matemático ---
    st.markdown(r"### 📐 O Rigor da Matriz Hat e Resíduos")
    st.markdown(r"Para detectar desvios, utilizamos a matriz hat $\mathbf{H} = \mathbf{X}(\mathbf{X}^T\mathbf{X})^{-1}\mathbf{X}^T$, cujos elementos diagonais $h_{ii}$ quantificam o poder de alavancagem de cada observação.")
    
    st.latex(r"d_i = \frac{e_i}{\hat{\sigma} \sqrt{1 - h_{ii}}}, \quad t_i = \frac{e_i}{\hat{\sigma}_{(i)} \sqrt{1 - h_{ii}}}")
    
    # --- Dedução Analítica ---
    st.markdown(r"### 🛠️ Decomposição da Variabilidade")
    st.latex(r"\text{Var}(e_i) = \sigma^2(1 - h_{ii})")
    st.latex(r"\hat{\sigma}^2 = \frac{SQRes}{n - p}")
    st.latex(r"t_i = \frac{e_i}{\hat{\sigma}_{(i)} \sqrt{1 - h_{ii}}}")
    
    # --- Simulador Interativo ---
    st.markdown(r"### 📊 Analisador de Resíduos em Tempo Real")
    
    col1, col2 = st.columns(2)
    with col1:
        tipo_erro = st.selectbox(r"Estrutura do Ruído", [r"Normal", r"Heterocedástico", r"Outlier"], key=r"tipo_erro_subtopico_2")
        n_pontos = st.slider(r"Tamanho da Amostra", 20, 200, 100, key=r"n_pontos_subtopico_2")
    with col2:
        mostrar_reta = st.toggle(r"Exibir Reta de Regressão", value=True, key=r"toggle_reta_subtopico_2")
        nivel_sig = st.number_input(r"Nível de Significância", 0.01, 0.10, 0.05, key=r"alpha_subtopico_2")
    
    # Lógica do Simulador
    x = np.linspace(0, 10, n_pontos)
    if tipo_erro == r"Normal":
        y = 2 * x + np.random.normal(0, 1, n_pontos)
    elif tipo_erro == r"Heterocedástico":
        y = 2 * x + np.random.normal(0, x/2, n_pontos)
    else:
        y = 2 * x + np.random.normal(0, 1, n_pontos)
        y[10] += 15
    
    slope, intercept, _, _, _ = stats.linregress(x, y)
    residuos = y - (slope * x + intercept)
    
    fig = make_subplots(rows=1, cols=2, subplot_titles=(r"Resíduos vs. Ajustados", r"Q-Q Plot"))
    fig.add_trace(go.Scatter(x=slope*x + intercept, y=residuos, mode="markers", name=r"Resíduos"), row=1, col=1)
    fig.add_trace(go.Scatter(x=stats.probplot(residuos, dist="norm")[0][0], y=stats.probplot(residuos, dist="norm")[0][1], mode="markers", name=r"Quantis"), row=1, col=2)
    
    fig.update_layout(template="plotly_white", height=420, margin=dict(l=55, r=30, t=65, b=55, pad=4))
    fig.update_xaxes(title_text=r"Valores Ajustados", row=1, col=1, fixedrange=True)
    fig.update_yaxes(title_text=r"Resíduos", row=1, col=1, fixedrange=True)
    st.plotly_chart(fig, use_container_width=True, key=r"plotly_chart_subtopico_2")
    
    st.info(f"O modelo apresenta um desvio de comportamento relacionado a {tipo_erro}. Analise o QQ-Plot: se os pontos se afastarem da diagonal, a suposição de normalidade está comprometida para n={n_pontos}.")
    
    # --- Exemplo Prático ---
    with st.container(border=True):
        st.markdown(r"##### 📖 Exemplo Resolvido: Identificação de Outlier em Frota")
        st.markdown(r"Em um estudo de manutenção de frotas ($n=5$), identificou-se uma observação crítica ($h_{55} = 0.85$) com resíduo $e_5 = 50$ e erro padrão residual $\hat{\sigma} = 20$.")
        st.latex(r"e_5 = 50, \hat{\sigma} = 20, h_{55} = 0.85")
        st.markdown(r"**Desenvolvimento Aritmético Passo a Passo:**")
        st.markdown(r"- Cálculo da alavancagem: $\sqrt{1 - 0.85} = \sqrt{0.15} \approx 0.387$")
        st.markdown(r"- Cálculo do resíduo padronizado: $d_5 = 50 / (20 \times 0.387) \approx 6.46$")
        st.success(r"Conclusão: O valor de $d_5 = 6.46$ excede largamente o limiar crítico de 2. Este ponto representa um outlier extremo que exige revisão na coleta de dados.")

    st.markdown('---')
    st.markdown('##### 📚 Referências Bibliográficas Consolidadas (Rodapé da Aula)')
    for ref in metadata['referencias_bibliograficas_finais']:
        st.markdown(f'- {ref}')

